async function exportBackup(){if(backupPassphrase.value.length<12){backupStatus.value='请设置至少 12 个字符的备份密码；YOSAKI 不会保存这个密码。';return};backupBusy.value=true;backupStatus.value='';try{const form=new FormData();form.set('passphrase',backupPassphrase.value);const response=await fetch('/api/system/backup/export',{method:'POST',credentials:'same-origin',body:form});if(!response.ok){const body=await response.json().catch(()=>({}));throw new Error(body.detail||`备份导出失败（${response.status}）`)}const blob=await response.blob();const disposition=response.headers.get('content-disposition')||'';const name=disposition.match(/filename="([^"]+)"/)?.[1]||'yosaki-backup.ybackup';const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;link.click();URL.revokeObjectURL(url);backupStatus.value='加密备份已导出。请将文件与备份密码分开保管。'}catch(e){backupStatus.value=e instanceof Error?e.message:'备份导出失败'}finally{backupBusy.value=false}}
async function importBackup(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;try{if(file.size>128*1024*1024)throw new Error('备份文件不能超过 128 MB');if(backupPassphrase.value.length<12)throw new Error('请输入创建该备份时使用的至少 12 位密码');if(!window.confirm('恢复将替换当前角色、对话、记忆、模型配置、MCP 和插件数据；登录会话会被清除。模型 API Key 与 MCP 密钥不在备份中，恢复后需重新配置。确定继续吗？'))return;backupBusy.value=true;const form=new FormData();form.set('confirm_replace','true');form.set('passphrase',backupPassphrase.value);form.set('backup',file,file.name);const response=await fetch('/api/system/backup/import',{method:'POST',credentials:'same-origin',body:form});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.detail||`恢复失败（${response.status}）`);backupStatus.value=body.message||'备份已恢复';authenticated.value=false;authReady.value=true;authDraft.value.password='';authDraft.value.confirmPassword='';workspaceView.value='welcome';openWindows.value=[];messages.value=[];window.history.pushState({},'','/')}catch(e){backupStatus.value=e instanceof Error?e.message:'备份文件无效或恢复失败'}finally{backupBusy.value=false;input.value=''}}

