async function loadModels() { try { modelProfiles.value = await api<ModelProfile[]>('/api/models'); if (!modelProfileId.value && modelProfiles.value.length) { modelProfileId.value = modelProfiles.value[0].id; model.value = modelProfiles.value[0].name } } catch { /* backend may be offline */ } }
function startNewModel() { editingModelId.value = null; modelKeyInput.value = ''; modelTestStatus.value = ''; modelDraft.value = { name: '我的模型', provider_name: 'OpenAI Compatible', base_url: 'https://api.openai.com/v1', model_name: '', protocol: 'openai_compatible', temperature: 0.8, top_p: 1, max_tokens: 2048, context_limit: 32768, supports_streaming: true, enabled: true } }
