const characterStatus=ref('')
const characterBusy=ref(false)
const characterDeletePending=ref(false)
const characterCardBusy=ref(false)
const characterCardFileInput=ref<HTMLInputElement|null>(null)
type CharacterDraft = Pick<Character, 'name'|'subtitle'|'mood'|'system_prompt'|'greeting'|'enabled'|'default_model_id'>
const savedCharacterDrafts = ref<Record<number, CharacterDraft>>({})
function characterDraft(character: Character): CharacterDraft { return { name: character.name, subtitle: character.subtitle, mood: character.mood, system_prompt: character.system_prompt, greeting: character.greeting, enabled: character.enabled, default_model_id: character.default_model_id } }
function rememberCharacter(character: Character) { savedCharacterDrafts.value[character.id] = characterDraft(character) }
const characterDirty = computed(() => !!current.value && !!savedCharacterDrafts.value[current.value.id] && JSON.stringify(characterDraft(current.value)) !== JSON.stringify(savedCharacterDrafts.value[current.value.id]))
function discardCharacterDraft() { const saved = current.value && savedCharacterDrafts.value[current.value.id]; if (saved) Object.assign(current.value, saved) }
function confirmLeaveCharacterDraft() { if (!characterDirty.value) return true; if (!window.confirm('当前角色资料尚未保存。确定放弃这些修改吗？')) return false; discardCharacterDraft(); return true }
function onCharacterSelection(event: Event) { const input = event.target as HTMLSelectElement; const next = Number(input.value); if (next === activeCharacter.value) return; if (!confirmLeaveCharacterDraft()) { input.value = String(activeCharacter.value); return } void selectCharacter(next) }
function warnUnsavedCharacter(event: BeforeUnloadEvent) { if (!characterDirty.value) return; event.preventDefault(); event.returnValue = '' }
async function persistActiveCharacter(){try{localStorage.setItem('YOSAKI.active-character',String(activeCharacter.value))}catch{}}
async function selectCharacter(characterId:number){activeCharacter.value=characterId;conversations.value=[];activeConversation.value=null;messages.value=[];characterDeletePending.value=false;modelProfileId.value=current.value.default_model_id;model.value=modelProfiles.value.find(profile=>profile.id===modelProfileId.value)?.name||'YOSAKI · demo';await persistActiveCharacter();await Promise.all([loadConversations(),loadPromptBlocks(),loadMemories()]);const latest=conversations.value[0];if(latest)await selectConversation(latest);else{await loadMemories();conversationStatus.value='该角色还没有对话'}}
async function exportCharacterCard(){if(!current.value)return;characterCardBusy.value=true;characterStatus.value='';try{const response=await fetch(`/api/characters/${current.value.id}/export`,{credentials:'same-origin'});if(!response.ok)throw new Error((await response.json().catch(()=>null))?.detail||`导出失败（${response.status}）`);const blob=await response.blob();const link=document.createElement('a');const url=URL.createObjectURL(blob);link.href=url;link.download=`yosaki-character-${current.value.id}.json`;link.click();URL.revokeObjectURL(url);characterStatus.value='角色卡 JSON 已导出；文件不含对话、记忆和密钥。'}catch(error){characterStatus.value=error instanceof Error?error.message:'角色卡导出失败'}finally{characterCardBusy.value=false}}
async function importCharacterCard(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;characterCardBusy.value=true;characterStatus.value='';try{if(file.size>256*1024)throw new Error('角色卡文件不能超过 256 KB');let card:any;try{card=JSON.parse(await file.text())}catch{throw new Error('文件不是有效的 JSON')};if(card.format!=='yosaki-character-card'||card.version!==1||!card.character)throw new Error('不支持的 YOSAKI 角色卡格式');const blockCount=Array.isArray(card.prompt_blocks)?card.prompt_blocks.length:0;if(!window.confirm(`将导入角色“${card.character.name||'未命名角色'}”和 ${blockCount} 个提示词块，并作为新角色添加；不会覆盖现有角色，也不会导入对话、记忆或默认模型。继续吗？`))return;if(!confirmLeaveCharacterDraft())return;const created=await api<Character>('/api/characters/import',{method:'POST',body:JSON.stringify(card)});const imported=characterFromApi(created,characters.value.length);characters.value.unshift(imported);rememberCharacter(imported);await selectCharacter(created.id);characterStatus.value=`角色卡已导入为新角色“${created.name}”`}catch(error){characterStatus.value=error instanceof Error?error.message:'角色卡导入失败'}finally{characterCardBusy.value=false;input.value=''}}

async function createCharacter(){const name=window.prompt('新角色名称','新角色');if(!name)return;const trimmed=name.trim();if(!trimmed||!confirmLeaveCharacterDraft())return;characterBusy.value=true;characterStatus.value='';try{const created=await api<Character>('/api/characters',{method:'POST',body:JSON.stringify({name:trimmed,subtitle:'由你创建的新角色',mood:'等待第一次对话',system_prompt:'',greeting:'你好，我是新角色。',enabled:true})});const added=characterFromApi(created,characters.value.length);characters.value.unshift(added);rememberCharacter(added);await selectCharacter(created.id);characterStatus.value=`已创建角色：${created.name}`}catch(error){characterStatus.value=error instanceof Error?error.message:'创建角色失败'}finally{characterBusy.value=false}}
async function duplicateCurrentCharacter(){if(!current.value)return;if(!window.confirm(`复制“${current.value.name}”？会复制角色资料与提示词块，不会复制聊天和记忆。`))return;if(!confirmLeaveCharacterDraft())return;characterBusy.value=true;characterStatus.value='';try{const created=await api<Character>(`/api/characters/${current.value.id}/duplicate`,{method:'POST'});const added=characterFromApi(created,characters.value.length);characters.value.unshift(added);rememberCharacter(added);await selectCharacter(created.id);characterStatus.value=`已复制角色：${created.name}`}catch(error){characterStatus.value=error instanceof Error?error.message:'复制角色失败'}finally{characterBusy.value=false}}
async function confirmDeleteCharacter(){if(!current.value)return;if(characters.value.length<=1){characterStatus.value='工作区至少要保留一个角色；请先新建或复制其他角色。';characterDeletePending.value=false;return}if(!characterDeletePending.value){characterDeletePending.value=true;characterStatus.value='删除会同时清空该角色的对话、工具记录、记忆和摘要，无法恢复。';return}characterBusy.value=true;characterStatus.value='';try{const deletedId=current.value.id;await api(`/api/characters/${deletedId}`,{method:'DELETE'});characters.value=characters.value.filter(item=>item.id!==deletedId);delete savedCharacterDrafts.value[deletedId];characterDeletePending.value=false;if(characters.value.length){await selectCharacter(characters.value[0].id)}else{characterStatus.value='工作区至少要保留一个角色。'}characterStatus.value='角色已删除'}catch(error){characterStatus.value=error instanceof Error?error.message:'删除角色失败'}finally{characterBusy.value=false}}
async function loadCharacters() { try { const data = await api<any[]>('/api/characters'); if (data.length) { characters.value = data.map(characterFromApi); savedCharacterDrafts.value = Object.fromEntries(characters.value.map(character => [character.id, characterDraft(character)])); const savedId=Number(localStorage.getItem('YOSAKI.active-character')||0); if (savedId && characters.value.some(c=>c.id===savedId)) activeCharacter.value=savedId; else if (!characters.value.some(c => c.id === activeCharacter.value)) activeCharacter.value = characters.value[0].id; apiOnline.value = true; await loadPromptBlocks(); await loadLatestConversation(); await loadMemories() } } catch { apiOnline.value = false } }
async function exportConversation(conversation:Conversation,format:'json'|'markdown') { try { const response=await fetch(`/api/conversations/${conversation.id}/export?format=${format}`,{credentials:'same-origin'}); if(!response.ok)throw new Error((await response.json().catch(()=>null))?.detail||`导出失败（${response.status}）`);const blob=await response.blob();const link=document.createElement('a');const url=URL.createObjectURL(blob);link.href=url;link.download=`${(conversation.title||'conversation').replace(/[^\p{L}\p{N}._-]+/gu,'_').slice(0,60)||'conversation'}.${format==='json'?'json':'md'}`;link.click();URL.revokeObjectURL(url);conversationStatus.value=`已导出 ${format==='json'?'JSON':'Markdown'}`}catch(error){conversationStatus.value=error instanceof Error?error.message:'导出失败'} }
async function loadConversations(){try{conversations.value=await api<Conversation[]>(`/api/conversations?character_id=${activeCharacter.value}`)}catch{conversations.value=[]}}
async function loadLatestConversation() { try { await loadConversations(); if (conversations.value.length) { activeConversation.value = conversations.value[0].id; modelProfileId.value=conversations.value[0].model_profile_id ?? current.value.default_model_id; model.value=modelProfiles.value.find(profile=>profile.id===modelProfileId.value)?.name||'YOSAKI · demo'; await loadMessages(conversations.value[0].id) } else { activeConversation.value = null; modelProfileId.value=current.value.default_model_id; model.value=modelProfiles.value.find(profile=>profile.id===modelProfileId.value)?.name||'YOSAKI · demo'; messages.value = [] } } catch { /* demo mode */ } }
async function renameConversation(conversation: Conversation) { const next=window.prompt('重命名对话',conversation.title||'新的对话'); if(next===null)return; const title=next.trim(); if(!title)return; try { const saved=await api<Conversation>(`/api/conversations/${conversation.id}`,{method:'PATCH',body:JSON.stringify({title})}); Object.assign(conversation,saved); conversationStatus.value='对话名称已更新' } catch(error) { conversationStatus.value=error instanceof Error?error.message:'重命名失败' } }
async function selectConversation(conversation: Conversation) { if(conversationBusy.value)return; conversationBusy.value=true; conversationStatus.value=''; try { activeConversation.value=conversation.id; modelProfileId.value=conversation.model_profile_id ?? current.value.default_model_id; model.value=modelProfiles.value.find(profile=>profile.id===modelProfileId.value)?.name||'YOSAKI · demo'; await loadMessages(conversation.id); await loadMemories(); conversationStatus.value=`已切换：${conversation.title||'新的对话'}` } catch(error) { conversationStatus.value=error instanceof Error?error.message:'加载对话失败' } finally { conversationBusy.value=false } }
async function deleteConversation(conversation:Conversation){if(!window.confirm(`删除“${conversation.title||'新的对话'}”？此操作会删除该对话的消息、工具记录和摘要。`))return;conversationBusy.value=true;try{await api(`/api/conversations/${conversation.id}`,{method:'DELETE'});conversations.value=conversations.value.filter(item=>item.id!==conversation.id);if(activeConversation.value===conversation.id){activeConversation.value=null;messages.value=[];summaryDraft.value='';await loadMemories()}conversationStatus.value='对话已删除'}catch(error){conversationStatus.value=error instanceof Error?error.message:'删除对话失败'}finally{conversationBusy.value=false}}
async function loadMessages(conversationId: number) { const data = await api<any[]>(`/api/conversations/${conversationId}/messages`); messages.value = data.map(item => ({ id:item.id, role:item.role, content:item.content||'', model:item.model||undefined, time:timeOf(item.created_at), toolRuns:item.tool_runs, toolBatchRunIds:item.tool_batch_run_ids, toolBatchStatus:item.tool_batch_status })).filter(item => item.role === 'user' || item.role === 'assistant') }
function rememberRoute() { try { localStorage.setItem('YOSAKI.last-route', window.location.pathname + window.location.search) } catch { /* storage may be unavailable */ } }
function queryWindowKind(): FeatureKind | null { const kind = new URLSearchParams(window.location.search).get('window'); return features.some(item => item.kind === kind) ? kind as FeatureKind : null }
function syncWindowUrl(kind: FeatureKind | null, replace = false) { const target = kind ? `/hub?window=${encodeURIComponent(kind)}` : '/hub'; (replace ? window.history.replaceState : window.history.pushState).call(window.history, {}, '', target); rememberRoute() }
function openFeaturePage(kind: FeatureKind) { const existing=openWindows.value.find(item=>item.kind===kind);if(existing){existing.minimized=false;focusWindow(existing.id,false)}else { openWindow(kind,false); } fullPageKind.value=kind;window.history.pushState({},'','/'+kind);rememberRoute();clampWindowsToViewport() }
function goHub() { workspaceView.value = 'hub'; syncWindowUrl(null) }
function goWelcome() { closeAll(); workspaceView.value = 'welcome'; window.history.pushState({}, '', '/'); rememberRoute() }
function newChat() { activeConversation.value = null; messages.value = []; modelProfileId.value=current.value.default_model_id; model.value=modelProfiles.value.find(profile=>profile.id===modelProfileId.value)?.name||'YOSAKI · demo'; conversationStatus.value='新对话'; openWindow('chat') }
function feature(kind: FeatureKind) { return features.find(item => item.kind === kind)! }
function openWindow(kind: FeatureKind, syncUrl = true) { workspaceView.value = 'hub'; fullPageKind.value=null; const existing = openWindows.value.find(item => item.kind === kind); if (existing) { existing.minimized = false; focusWindow(existing.id,syncUrl) } else { const index = openWindows.value.length; openWindows.value.push({ id: `${kind}-${Date.now()}`, kind, title: feature(kind).title, x: 110 + (index % 4) * 28, y: 72 + (index % 4) * 24, width: kind === 'chat' ? 720 : 560, height: kind === 'chat' ? 650 : 520, zIndex: ++zCounter.value, minimized: false, maximized: false }) }; if(syncUrl)syncWindowUrl(kind); saveLayout() }
function closeWindow(id: string) { const closing=openWindows.value.find(item=>item.id===id);openWindows.value = openWindows.value.filter(item => item.id !== id);if(closing&&fullPageKind.value===closing.kind){fullPageKind.value=null;window.history.replaceState({},'','/hub');rememberRoute()}else if(closing&&queryWindowKind()===closing.kind){const next=[...openWindows.value].sort((a,b)=>b.zIndex-a.zIndex)[0];syncWindowUrl(next?.kind??null,true)}saveLayout() }
function closeAll() { openWindows.value = []; fullPageKind.value=null; if(window.location.pathname==='/hub'&&window.location.search)syncWindowUrl(null,true);saveLayout() }
function focusWindow(id: string, syncUrl = true) { const item = openWindows.value.find(window => window.id === id); if (item) { item.zIndex = ++zCounter.value; if(syncUrl&&!fullPageKind.value&&window.location.pathname==='/hub'&&queryWindowKind()!==item.kind)syncWindowUrl(item.kind,true) } }
function toggleMinimize(item: WindowInstance) { item.minimized = !item.minimized; focusWindow(item.id); saveLayout() }
function toggleMaximize(item: WindowInstance) { item.maximized = !item.maximized; item.minimized = false; focusWindow(item.id); saveLayout() }
function windowStyle(item: WindowInstance) { if (item.maximized) return { zIndex: item.zIndex }; if (item.minimized) return { zIndex: item.zIndex, left: `${item.x}px`, top: `${item.y}px`, width: '250px', height: '46px' }; return { zIndex: item.zIndex, left: `${item.x}px`, top: `${item.y}px`, width: `${item.width}px`, height: `${item.height}px` } }
function startDrag(event: PointerEvent, item: WindowInstance) { const target = event.target as HTMLElement; if (target.closest('button, input, textarea, select') || item.maximized || fullPageKind.value===item.kind) return; focusWindow(item.id); dragState.value = { id: item.id, dx: event.clientX - item.x, dy: event.clientY - item.y }; (event.currentTarget as HTMLElement).setPointerCapture?.(event.pointerId) }
function onPointerMove(event: PointerEvent) { const state = dragState.value; if (!state) return; const item = openWindows.value.find(window => window.id === state.id); if (item) { item.x = Math.max(8, Math.min(window.innerWidth-item.width-8,event.clientX-state.dx)); item.y = Math.max(58, Math.min(window.innerHeight-54,event.clientY-state.dy)) } }
function stopDrag() { const wasDragging=!!dragState.value; dragState.value = null; const resized=syncWindowSizes(); if(wasDragging||resized){clampWindowsToViewport();saveLayout()} }
function clampWindowsToViewport() { for(const item of openWindows.value){item.width=Math.max(320,Math.min(item.width,Math.max(320,window.innerWidth-32)));item.height=Math.max(180,Math.min(item.height,Math.max(180,window.innerHeight-100)));item.x=Math.max(8,Math.min(item.x,window.innerWidth-item.width-8));item.y=Math.max(58,Math.min(item.y,window.innerHeight-item.height-8))} }
function syncWindowSizes() { let changed=false; for(const item of openWindows.value){if(item.minimized||item.maximized||fullPageKind.value===item.kind)continue;const element=document.querySelector<HTMLElement>(`[data-window-id="${CSS.escape(item.id)}"]`);if(!element)continue;const width=Math.round(element.getBoundingClientRect().width),height=Math.round(element.getBoundingClientRect().height);if(width>0&&height>0&&(item.width!==width||item.height!==height)){item.width=width;item.height=height;changed=true}}return changed }
function saveLayout() { try { const serialized=JSON.stringify(openWindows.value); localStorage.setItem('YOSAKI.window-layout.v1', serialized); localStorage.setItem('YOSAKI.last-open-windows', serialized); rememberRoute() } catch { /* storage may be unavailable */ } }
function restoreLayout() { try { const saved = JSON.parse(localStorage.getItem('YOSAKI.window-layout.v1') || '[]'); if (!Array.isArray(saved)) return; const allowed = new Set(features.map(item => item.kind)); const valid = saved.filter((item: any): item is WindowInstance => item && typeof item === 'object' && allowed.has(item.kind) && typeof item.id === 'string').map((item: WindowInstance) => ({ ...item, x: Number.isFinite(item.x) ? Math.max(8,item.x) : 110, y: Number.isFinite(item.y) ? Math.max(58,item.y) : 72, width: Number.isFinite(item.width) ? Math.max(320,item.width) : 560, height: Number.isFinite(item.height) ? Math.max(240,item.height) : 520, zIndex: Number.isFinite(item.zIndex) ? item.zIndex : 10, minimized: item.minimized === true, maximized: item.maximized === true })); openWindows.value = valid.filter((item,index,array)=>array.findIndex(candidate=>candidate.kind===item.kind)===index); clampWindowsToViewport(); zCounter.value = Math.max(zCounter.value, ...openWindows.value.map(item => Number(item.zIndex) || 0)) } catch { openWindows.value = [] } }
function appendFallback(text: string) { messages.value.push({ role: 'assistant', content: `我听见了，${current.value.name}会把这句话放在心里。\n\n这件事可以从很小的地方开始：先保留一个能让你安心回来的角落，再让它一点一点长成你想要的样子。\n\n你刚才说的是：${text}`, time: timeOf(), model: 'YOSAKI · demo' }) }
async function consumeChatStream(response: Response, target?: Message) {
  if (!response.ok || !response.body) throw new Error('聊天服务不可用')
  apiOnline.value = true
  const reader=response.body.getReader(), decoder=new TextDecoder(); let buffer=''; let assistantMessage=target
  while(true){
    const {value,done}=await reader.read(); if(done) break
    buffer+=decoder.decode(value,{stream:true}); const events=buffer.split('\n\n'); buffer=events.pop()||''
    for(const event of events){
      const eventName=event.match(/^event: (.+)$/m)?.[1], dataText=event.match(/^data: (.+)$/m)?.[1]; if(!dataText) continue
      const data=JSON.parse(dataText)
      if(eventName==='message_start'){
        if(data.conversation_id) activeConversation.value=data.conversation_id
        if(!assistantMessage){assistantMessage={role:'assistant',content:'',time:timeOf(),model:data.model,toolRuns:[]};messages.value.push(assistantMessage)}
      } else if(eventName==='text_delta' && assistantMessage){assistantMessage.content+=data.text}
      else if(eventName==='tool_waiting_confirmation'){
        if(!assistantMessage){assistantMessage={role:'assistant',content:'',time:timeOf(),toolRuns:[]};messages.value.push(assistantMessage)}
        assistantMessage.toolRuns ||= []
        assistantMessage.toolRuns.push({...data,status:'pending_confirmation'})
      } else if(eventName==='tool_batch_waiting' && assistantMessage){assistantMessage.toolBatchRunIds=data.run_ids;assistantMessage.toolBatchStatus='awaiting_confirmation'}
      else if(eventName==='error'){if(assistantMessage)assistantMessage.toolBatchStatus='failed';errorMessage.value=data.message || '聊天请求失败'}
      else if(eventName==='message_complete' && assistantMessage){assistantMessage.toolBatchStatus='completed'}
    }
  }
}
function persistStoppedAssistant(){const message=[...messages.value].reverse().find(item=>item.role==='assistant');if(message)message.toolBatchStatus='stopped'}
function stopGeneration(){if(!isStreaming.value||!abortController.value)return;streamStopped.value=true;abortController.value.abort()}
async function regenerateLast(){if(isStreaming.value||activeConversation.value===null)return;isStreaming.value=true;errorMessage.value='';abortController.value=new AbortController();try{const response=await fetch('/api/chat/regenerate',{method:'POST',headers:{'Content-Type':'application/json'},signal:abortController.value.signal,body:JSON.stringify({character_id:activeCharacter.value,conversation_id:activeConversation.value,message:'',model:model.value,model_profile_id:modelProfileId.value})});if(!response.ok)throw new Error((await response.json().catch(()=>null))?.detail||'重新生成失败');messages.value=messages.value.filter((message,index)=>!(message.role==='assistant'&&index===messages.value.length-1));await consumeChatStream(response)}catch(error){if((error as Error)?.name!=='AbortError')errorMessage.value=error instanceof Error?error.message:'重新生成失败'}finally{isStreaming.value=false;abortController.value=null}}
async function send() {
  const text=draft.value.trim(); if(!text||isStreaming.value)return
  messages.value.push({role:'user',content:text,time:timeOf()}); draft.value=''; isStreaming.value=true; errorMessage.value=''
  abortController.value=new AbortController();streamStopped.value=false
  try { const response=await fetch('/api/chat/stream',{method:'POST',headers:{'Content-Type':'application/json'},signal:abortController.value.signal,body:JSON.stringify({character_id:activeCharacter.value,conversation_id:activeConversation.value,message:text,model:model.value,model_profile_id:modelProfileId.value})}); if(!response.ok){apiOnline.value=true;const detail=(await response.json().catch(()=>null))?.detail;errorMessage.value=detail||`聊天请求失败（${response.status}）`;return}; await consumeChatStream(response); await loadConversations() }
  catch(error){if((error as Error)?.name==='AbortError'){errorMessage.value='已停止生成';persistStoppedAssistant()}else{apiOnline.value=false;errorMessage.value=error instanceof Error?error.message:'后端不可用';appendFallback(text)}}
  finally{isStreaming.value=false;abortController.value=null}
}
async function decideTool(message:Message, run:ToolRunUi, approve:boolean){
  if(toolDecisionBusy.value!==null)return
  toolDecisionBusy.value=run.run_id
  try{const result=await api<any>(`/api/chat/tool-runs/${run.run_id}/decision`,{method:'POST',body:JSON.stringify({approve})});run.status=result.status;run.result=result.result;run.error=result.error;message.toolBatchStatus='awaiting_confirmation'}
  catch(error){errorMessage.value=error instanceof Error?error.message:'工具确认/执行失败'}
  finally{toolDecisionBusy.value=null}
}
async function continueAfterTools(message:Message){
  const runId=message.toolBatchRunIds?.[0]; if(!runId||message.toolRuns?.some(run=>run.status==='pending_confirmation'))return
  isStreaming.value=true; message.toolBatchStatus='completed'; errorMessage.value=''
  try{const response=await fetch(`/api/chat/tool-runs/${runId}/continue`,{method:'POST'});await consumeChatStream(response)}
  catch(error){message.toolBatchStatus='failed';errorMessage.value=error instanceof Error?error.message:'继续生成失败'}
  finally{isStreaming.value=false}
}

async function setCharacterDefaultModel(){if(!current.value)return;modelProfileId.value=current.value.default_model_id;model.value=modelProfiles.value.find(profile=>profile.id===modelProfileId.value)?.name||'YOSAKI · demo';await saveCharacter()}
async function saveCharacter() { if (!current.value || !apiOnline.value) return; const character=current.value; const payload=characterDraft(character); saving.value = true; characterStatus.value=''; try { await api(`/api/characters/${character.id}`, { method: 'PATCH', body: JSON.stringify(payload) }); savedCharacterDrafts.value[character.id]=payload; character.last = character.greeting || character.last; characterStatus.value='角色资料已保存' } catch (error) { characterStatus.value = error instanceof Error ? error.message : '保存失败' } finally { saving.value = false } }
function handlePopState() { const pageKind=routeWindowKind(window.location.pathname);workspaceView.value = window.location.pathname === '/hub' || !!pageKind ? 'hub' : 'welcome';const linkedWindow=pageKind ?? (workspaceView.value==='hub'?queryWindowKind():null);if(linkedWindow)openWindow(linkedWindow,false);fullPageKind.value=pageKind;rememberRoute();clampWindowsToViewport() }
onMounted(() => { if(window.innerWidth<=900)showNav.value=false; rememberRoute(); window.addEventListener('resize',clampWindowsToViewport); window.addEventListener('beforeunload',warnUnsavedCharacter); refreshSpeechVoices(); if ('speechSynthesis' in window) window.speechSynthesis.addEventListener('voiceschanged',onSpeechVoicesChanged); void refreshAuth(); window.addEventListener('pointermove', onPointerMove); window.addEventListener('pointerup', stopDrag); window.addEventListener('popstate', handlePopState) })
onBeforeUnmount(() => { if ('speechSynthesis' in window) window.speechSynthesis.removeEventListener('voiceschanged',onSpeechVoicesChanged); stopSpeaking(); stopSpeechRecognition(); window.removeEventListener('pointermove', onPointerMove); window.removeEventListener('pointerup', stopDrag); window.removeEventListener('popstate', handlePopState); window.removeEventListener('resize',clampWindowsToViewport); window.removeEventListener('beforeunload',warnUnsavedCharacter) })
</script>
<template>
<div class="app-shell" :class="{ 'welcome-shell': workspaceView === 'welcome' }">
  <section v-if="!authReady" class="auth-page"><div class="auth-card"><div class="brand-mark">Y</div><h1>正在检查私人工作区…</h1><p>请稍候</p></div></section>
  <section v-else-if="!authenticated" class="auth-page"><div class="auth-orbit"></div><div class="auth-card"><div class="brand-mark">Y</div><span class="auth-kicker">YOSAKI · PRIVATE WORKSPACE</span><h1>{{setupRequired?'设置你的私人账户':'欢迎回来'}}</h1><p>{{setupRequired?'创建唯一的管理员账户。密码仅在服务器保存为加盐哈希。':'登录后继续进入你的工作台。'}}</p><form @submit.prevent="submitAuth"><label>账户名称<input v-model="authDraft.username" required minlength="3" maxlength="40" autocomplete="username" placeholder="例如：owner"/></label><label>密码<input v-model="authDraft.password" required minlength="12" maxlength="256" type="password" :autocomplete="setupRequired?'new-password':'current-password'" placeholder="至少 12 个字符"/></label><label v-if="setupRequired">确认密码<input v-model="authDraft.confirmPassword" required minlength="12" maxlength="256" type="password" autocomplete="new-password" placeholder="再次输入密码"/></label><p v-if="authError" class="auth-error" role="alert">{{authError}}</p><button class="enter-btn auth-submit" :disabled="authBusy">{{authBusy?'请稍候…':setupRequired?'创建账户并进入':'登录并进入'}} <ArrowRight :size="17"/></button></form><div class="auth-privacy"><ShieldCheck :size="14"/> 单用户 · HttpOnly 会话 · 仅本地设置密码</div></div><footer class="auth-footer">尚未设置密码前，所有应用数据接口保持锁定。</footer></section>
  <section v-else-if="workspaceView === 'welcome'" class="welcome-page">
    <div class="welcome-orbit orbit-one"></div><div class="welcome-orbit orbit-two"></div><div class="welcome-grid"></div>
    <header class="welcome-brand"><div class="brand-mark">Y</div><div><strong>YOSAKI</strong><span>your own sanctuary</span></div><span class="private-badge"><span></span> private workspace</span></header>
    <div class="welcome-content">
      <div class="welcome-copy"><span class="welcome-kicker">A SPACE FOR YOUR CONNECTIONS</span><h1>把想说的话，<em>留在这里。</em></h1><p>一个属于你和阿夜的可塑空间。聊天只是其中一扇门，你也可以从角色、模型、记忆和工具开始。</p><button class="enter-btn" @click="goHub">进入我的空间 <ArrowRight :size="17"/></button><div class="welcome-note"><ShieldCheck :size="14"/> 数据默认保存在你的本地工作区</div></div>
      <div class="welcome-preview"><div class="preview-window"><div class="preview-top"><span></span><span></span><span></span><small>YOSAKI / workspace</small></div><div class="preview-body"><div class="preview-nav"><div class="mini-logo">Y</div><div class="mini-line active"></div><div class="mini-line"></div><div class="mini-line"></div><div class="mini-line"></div></div><div class="preview-main"><span class="preview-label">YOUR SPACE</span><h2>从这里开始<br/><i>慢慢搭建。</i></h2><div class="preview-cards"><div></div><div></div><div></div></div></div></div></div></div>
    </div>
    <footer class="welcome-footer"><span>YOSAKI 0.2 / LOCAL FIRST</span><span>为阿夜保留一块自己的地方</span></footer>
  </section>

  <section v-else class="workspace-shell">
    <aside class="workspace-rail" :class="{ collapsed: !showNav }"><div class="rail-brand"><div class="brand-mark">Y</div><div v-if="showNav"><strong>YOSAKI</strong><span>your own sanctuary</span></div><button class="icon-btn quiet" @click="showNav=!showNav"><PanelLeft :size="17"/></button></div><div v-if="showNav" class="rail-body"><button class="home-link" @click="goHub"><Home :size="15"/> 工作台</button><div class="rail-section">功能</div><button v-for="item in features" :key="item.kind" class="rail-link" @click="openWindow(item.kind)"><component :is="item.icon" :size="16"/><span>{{item.title}}</span></button><div class="rail-bottom"><button class="home-link muted" @click="goWelcome"><ArrowRight :size="15" class="back-icon"/> 返回欢迎页</button><div class="rail-status"><span :class="{online:apiOnline}"></span>{{apiOnline?'本地后端已连接':'本地演示模式'}}</div><button class="home-link muted logout-link" :disabled="authBusy" @click="logout"><LogOut :size="15"/> 退出登录</button></div></div></aside>
    <main class="workspace-main"><header class="workspace-topbar"><div><span class="top-kicker">YOSAKI / WORKSPACE</span><h1>你的空间</h1></div><div class="workspace-actions"><span class="date-chip">{{dateLabel}}</span><button class="icon-btn" @click="openWindow('settings')"><Settings2 :size="18"/></button><button class="icon-btn mobile-only" @click="showNav=!showNav"><PanelLeft :size="18"/></button></div></header><section class="hub-content"><div class="hub-intro"><div><span class="hub-greeting">晚上好，</span><h2>今天想从哪里开始？</h2><p>这里不是一个固定的聊天窗口，而是你可以慢慢搭建的个人 AI 工作台。</p></div><div class="hub-orb"><div class="orb-core">阿</div><span>阿夜在线</span></div></div><div class="feature-grid"><button v-for="item in features" :key="item.kind" class="feature-card" @click="openWindow(item.kind)"><div class="feature-icon" :style="{color:item.accent,background:`${item.accent}18`}"><component :is="item.icon" :size="19"/></div><div class="feature-card-copy"><strong>{{item.title}}</strong><span>{{item.description}}</span><small>{{item.status}}</small></div><ArrowRight :size="16" class="feature-arrow"/></button></div><div class="hub-footnote"><Sparkles :size="15"/><span>拖动或放大功能窗口，把工作台变成你喜欢的样子。</span><button @click="newChat">快速开始聊天 <ArrowRight :size="14"/></button></div></section></main>
    <section class="window-layer">
      <article v-for="item in (fullPageKind ? openWindows.filter(window=>window.kind===fullPageKind) : activeWindows)" :key="item.id" class="floating-window" :data-window-id="item.id" :class="{ minimized:item.minimized, maximized:item.maximized, 'full-page-feature':fullPageKind===item.kind }" :style="windowStyle(item)" @pointerdown="focusWindow(item.id)">
        <header class="window-header" @pointerdown="startDrag($event,item)"><div class="window-title"><component :is="feature(item.kind).icon" :size="15" :style="{color:feature(item.kind).accent}"/><strong>{{item.title}}</strong></div><div class="window-controls"><button v-if="fullPageKind!==item.kind" title="作为独立页面打开" :aria-label="`将${item.title}作为独立页面打开`" @click.stop="openFeaturePage(item.kind)"><ArrowUpRight :size="14"/></button><button v-if="fullPageKind!==item.kind" @click.stop="toggleMinimize(item)"><Minus :size="14"/></button><button v-if="fullPageKind!==item.kind" @click.stop="toggleMaximize(item)"><Minimize2 v-if="item.maximized" :size="14"/><Maximize2 v-else :size="14"/></button><button :title="fullPageKind===item.kind?'返回工作台':'关闭窗口'" :aria-label="fullPageKind===item.kind?'返回工作台':`关闭${item.title}窗口`" @click.stop="closeWindow(item.id)"><X :size="14"/></button></div></header>
        <div v-if="!item.minimized" class="window-content">
          <div v-if="item.kind==='chat'" class="window-chat">
            <div class="chat-window-toolbar"><div class="avatar small" :style="{background:current.color}">{{current.name.slice(0,1)}}</div><div><strong>{{current.name}}</strong><span>{{current.subtitle}}</span></div><select class="model-select model-switch" v-model="modelProfileId" @change="model = modelProfiles.find(profile => profile.id === modelProfileId)?.name || 'YOSAKI · demo'"><option :value="null">YOSAKI · demo</option><option v-for="profile in modelProfiles" :key="profile.id" :value="profile.id">{{profile.name}} · {{profile.model_name}}</option></select><button class="icon-btn" title="配置模型" @click="openWindow('models')"><Settings2 :size="15"/></button></div>
            <div class="conversation-strip"><button class="new-conversation-btn" @click="newChat"><Plus :size="13"/>新对话</button><div class="conversation-list"><button v-for="conversation in conversations" :key="conversation.id" class="conversation-chip" :class="{active:activeConversation===conversation.id}" @click="selectConversation(conversation)"><span>{{conversation.title || '新的对话'}}</span><small>{{new Date(conversation.updated_at).toLocaleDateString('zh-CN',{month:'numeric',day:'numeric'})}}</small><b title="导出 JSON" @click.stop="exportConversation(conversation,'json')">J</b><b title="导出 Markdown" @click.stop="exportConversation(conversation,'markdown')">M</b><i @click.stop="deleteConversation(conversation)">×</i></button><span v-if="!conversations.length" class="conversation-empty">还没有已保存的对话</span></div><span class="conversation-status">{{conversationStatus}}</span></div>
            <div class="chat-scroll"><div v-if="!messages.length" class="empty-state"><MessageCircle :size="25"/><strong>{{current.greeting || '从一句话开始吧'}}</strong><span>对话内容会保存到本地 YOSAKI 数据库。</span></div><div class="messages"><div v-for="(message,index) in messages" :key="message.id || index" class="message-row" :class="message.role"><div v-if="message.role==='assistant'" class="avatar tiny" :style="{background:current.color}">{{current.name.slice(0,1)}}</div><div class="message-body"><div v-if="message.content" class="bubble" :class="message.role"><p v-for="(line,i) in message.content.split('\n')" :key="i">{{line||' '}}</p></div><div v-for="run in message.toolRuns||[]" :key="run.run_id" class="tool-confirm-card"><div class="tool-confirm-heading"><strong>{{run.plugin_name ? run.plugin_name + ' · ' : run.server_name + ' · '}}{{run.tool_name}}</strong><span :class="run.status">{{run.status==='pending_confirmation'?'等待你的确认':run.status==='success'?'已执行':run.status==='rejected'?'已拒绝':run.status==='running'?'执行中':run.status==='revoked'?'已撤销':'执行失败'}}</span></div><p>{{run.description}}</p><pre>{{JSON.stringify(run.arguments,null,2)}}</pre><div v-if="run.status==='pending_confirmation'" class="tool-confirm-actions"><button :disabled="toolDecisionBusy!==null" @click="decideTool(message,run,true)">确认执行</button><button class="reject" :disabled="toolDecisionBusy!==null" @click="decideTool(message,run,false)">拒绝</button></div><details v-if="run.result"><summary>查看工具结果</summary><pre>{{JSON.stringify(run.result,null,2)}}</pre></details><small v-if="run.error">{{run.error}}</small></div><div v-if="message.toolBatchRunIds?.length && !message.toolRuns?.some(run=>run.status==='pending_confirmation') && message.toolBatchStatus==='awaiting_confirmation'" class="continue-tools"><span>工具处理完毕，可以让阿夜继续回复</span><button  @click="continueAfterTools(message)">继续对话</button></div><div class="message-meta">{{message.time}} <span v-if="message.model">· {{message.model}}</span><button v-if="message.role==='assistant' && message.content" class="message-speak" title="朗读回复" @click="speakMessage(message,index)"><Volume2 :size="13"/></button><button v-if="message.role==='assistant' && index===messages.length-1" class="message-speak" title="重新生成" @click="regenerateLast"><RefreshCw :size="13"/></button></div></div></div><div v-if="isStreaming" class="message-row assistant"><div class="avatar tiny" :style="{background:current.color}">{{current.name.slice(0,1)}}</div><div class="bubble assistant typing"><span></span><span></span><span></span></div></div></div></div>
            <div class="composer-wrap"><div class="composer"><textarea v-model="draft" @keydown.enter.exact.prevent="send" placeholder="写下你想说的话…" rows="1"></textarea><div class="composer-tools"><div><button class="icon-btn"><Paperclip :size="17"/></button><button class="icon-btn" :disabled="speechRecognitionRunning" :title="speechRecognitionRunning ? '停止语音识别' : '语音转文字'" @click="requestSpeechInput"><Mic :size="17"/></button></div><button v-if="isStreaming" class="send-btn ready" title="停止生成" @click="stopGeneration"><X :size="16"/></button><button v-else class="send-btn" :class="{ready:draft.trim()}" @click="send"><Send :size="16"/></button></div></div></div>
          </div>
                    <div v-else-if="item.kind==='characters'" class="window-form"><div class="window-section-heading"><div><span class="section-eyebrow">CHARACTER CARD</span><h2>管理角色</h2><p>这些内容会进入角色的稳定提示词。</p></div><button class="primary-btn" :disabled="saving" @click="saveCharacter"><Save :size="15"/> {{saving?'保存中':'保存'}}</button></div><div class="character-management"><button class="secondary-btn" :disabled="characterBusy" @click="createCharacter">新建角色</button><button class="secondary-btn" :disabled="characterBusy" @click="duplicateCurrentCharacter">复制当前角色</button><button class="secondary-btn" :disabled="characterCardBusy" @click="exportCharacterCard">导出角色卡 JSON</button><button class="secondary-btn" :disabled="characterCardBusy" @click="characterCardFileInput?.click()">导入角色卡 JSON</button><input ref="characterCardFileInput" class="plugin-file-input" type="file" accept=".json,application/json" @change="importCharacterCard"/><button class="secondary-btn danger" :disabled="characterBusy" @click="confirmDeleteCharacter">{{characterDeletePending?'确认删除':'删除当前角色'}}</button><button v-if="characterDeletePending" class="text-btn" @click="characterDeletePending=false">取消删除</button></div><p class="character-status" role="status">{{characterDirty ? '角色资料有未保存修改' : '角色资料已保存'}}<span v-if="characterStatus && characterStatus!=='角色资料已保存'"> · {{characterStatus}}</span></p><label>当前角色<select :value="activeCharacter" @change="onCharacterSelection"><option v-for="character in characters" :key="character.id" :value="character.id">{{character.name}}</option></select></label><label>默认模型<select v-model="current.default_model_id" @change="setCharacterDefaultModel"><option :value="null">跟随当前聊天选择</option><option v-for="profile in modelProfiles" :key="profile.id" :value="profile.id">{{profile.name}} · {{profile.model_name}}</option></select></label><label>角色名称<input v-model="current.name" @input="characterStatus=''"/></label><label>角色简介<textarea v-model="current.subtitle" rows="2" @input="characterStatus=''"></textarea></label><label>核心人设<textarea v-model="current.system_prompt" rows="6" @input="characterStatus=''"></textarea></label><label>开场白<textarea v-model="current.greeting" rows="2" @input="characterStatus=''"></textarea></label><p role="status">{{promptNotice}}</p><button class="text-btn" @click="openWindow('memory'); previewContext()">查看已保存上下文</button><div class="prompt-block-editor"><div class="prompt-block-heading"><div><strong>提示词注入块</strong><span>按位置组合到模型系统提示中</span></div><button class="text-btn" @click="addPromptBlock"><Plus :size="14"/> 添加</button></div><div v-for="(block, blockIndex) in promptBlocks" :key="block.id" class="prompt-block-edit" @dragover.prevent @drop.prevent="draggedPrompt !== null && movePrompt(draggedPrompt, blockIndex)"><div class="prompt-actions"><button draggable="true" @dragstart="draggedPrompt=block.id" @dragend="draggedPrompt=null" title="拖动排序">⠿ 拖动</button><button :disabled="blockIndex===0" @click="movePrompt(block.id,blockIndex-1)">上移</button><button :disabled="blockIndex===promptBlocks.length-1" @click="movePrompt(block.id,blockIndex+1)">下移</button><label><input type="checkbox" v-model="block.enabled" @change="savePromptBlock(block)"/>启用</label><button @click="deletingPrompt=block.id">删除</button><template v-if="deletingPrompt===block.id"><button @click="removePrompt(block.id)">确认删除</button><button @click="deletingPrompt=null">取消</button></template></div><div class="prompt-block-row"><input v-model="block.name" @change="savePromptBlock(block)"/><select v-model="block.injection_position" @change="savePromptBlock(block)"><option value="system_start">system_start</option><option value="character_profile">character_profile</option><option value="scenario">scenario</option><option value="memory">memory</option><option value="examples">examples</option><option value="before_history">before_history</option><option value="after_history">after_history</option><option value="system_end">system_end</option></select></div><textarea v-model="block.content" rows="2" @change="savePromptBlock(block)"></textarea></div></div></div>          <div v-else-if="item.kind==='models'" class="window-form model-window"><div class="window-section-heading"><div><span class="section-eyebrow">MODEL PROFILES</span><h2>模型配置</h2><p>密钥只发送给后端保存，不会写入浏览器存储。</p></div><button class="primary-btn" @click="startNewModel"><Plus :size="15"/> 新建</button></div><div v-if="modelProfiles.length" class="model-list"><button v-for="profile in modelProfiles" :key="profile.id" class="model-list-item" :class="{selected:editingModelId===profile.id}" @click="editModel(profile)"><span class="model-state" :class="{configured:profile.api_key_configured}"></span><span><strong>{{profile.name}}</strong><small>{{profile.provider_name}} · {{profile.model_name}}</small></span><ChevronDown :size="14"/></button></div><div class="model-form-grid"><label>配置名称<input v-model="modelDraft.name" placeholder="例如：DeepSeek 日常"/></label><label>服务商<input v-model="modelDraft.provider_name" placeholder="OpenAI Compatible"/></label><label class="full-span">Base URL<input v-model="modelDraft.base_url" placeholder="https://api.example.com/v1"/></label><label>模型名称<input v-model="modelDraft.model_name" placeholder="例如：gpt-4o-mini"/></label><label>API Key<input v-model="modelKeyInput" type="password" autocomplete="new-password" :placeholder="editingModelId ? '留空则保留已有密钥' : '只在这里输入，不会回显'"/></label><label>Temperature<input v-model.number="modelDraft.temperature" type="number" min="0" max="2" step="0.1"/></label><label>Max Tokens<input v-model.number="modelDraft.max_tokens" type="number" min="1" step="1"/></label></div><div class="model-form-actions"><button class="secondary-btn" :disabled="modelSaving" @click="saveModel"><Save :size="15"/> {{modelSaving?'保存中…':'保存配置'}}</button><button class="text-btn" :disabled="!editingModelId" @click="testModel"><Zap :size="14"/> 测试真实连接</button></div><p v-if="modelTestStatus" class="model-feedback">{{modelTestStatus}}</p></div>          <div v-else-if="item.kind==='memory'" class="window-form memory-window"><div class="window-section-heading"><div><span class="section-eyebrow">MEMORY & CONTEXT</span><h2>把重要的事留下</h2><p>原始聊天记录不会被覆盖；记忆只是发送给模型时的参考材料。</p></div><button class="primary-btn" :disabled="previewBusy" @click="previewContext">{{previewBusy?'读取中…':'预览上下文'}}</button></div><div class="memory-controls"><input v-model="memorySearch" @change="loadMemories" placeholder="搜索已保存记忆"/><button class="secondary-btn" @click="loadMemories">搜索</button></div><div class="memory-settings"><label>最近历史条数<input v-model.number="contextSettings.history_limit" type="number" min="0" max="1000" @change="saveContextSettings"/></label><label class="check-label"><input v-model="contextSettings.memory_enabled" type="checkbox" @change="saveContextSettings"/>发送记忆</label><span>当前对话：{{activeConversation?'已选择':'尚未选择'}}</span></div><div class="memory-create"><select v-model="memoryDraft.scope"><option value="long">长期记忆（角色）</option><option value="temporary">临时记忆（当前对话）</option></select><textarea v-model="memoryDraft.content" rows="2" placeholder="例如：用户喜欢在夜里讨论创作，不喜欢被催促。"></textarea><button class="primary-btn" :disabled="memoryBusy" @click="createMemory">保存记忆</button></div><div class="memory-list"><article v-for="memory in memories" :key="memory.id" class="memory-item"><div><span class="memory-scope">{{memory.scope==='long'?'长期':'本对话'}}</span><p>{{memory.content}}</p><small>{{memory.enabled?'已启用':'已停用'}}</small></div><div class="memory-item-actions"><button @click="toggleMemory(memory)">{{memory.enabled?'停用':'启用'}}</button><button @click="deleteMemory(memory)">删除</button></div></article><p v-if="!memories.length" class="memory-empty">还没有匹配的记忆。</p></div><div class="summary-editor"><div><strong>当前对话摘要</strong><span>手动摘要会作为参考资料进入上下文，不会删除原始消息。</span></div><textarea v-model="summaryDraft" rows="4" placeholder="可选：记录这段对话的关键进展、约定和未完成事项。"></textarea><label class="check-label"><input v-model="summaryEnabled" type="checkbox"/>启用摘要</label><button class="text-btn" @click="saveSummary">保存摘要</button></div><p role="status">{{promptNotice}}</p><article v-for="(part,index) in previewMessages" :key="index" class="context-part"><strong>{{index+1}} · {{part.role}}</strong><pre>{{part.content || '（当前草稿为空）'}}</pre></article></div><div v-else-if="item.kind==='mcp'" class="window-form mcp-window"><div class="window-section-heading"><div><span class="section-eyebrow">MCP CONNECTORS</span><h2>MCP 与工具</h2><p>首版执行链默认要求用户确认；服务密钥只由后端保存。</p></div><button class="primary-btn" :disabled="mcpBusy" @click="saveMcp">{{mcpBusy?'处理中…':'保存服务'}}</button></div><div class="mcp-server-list"><button v-for="server in mcpServers" :key="server.id" class="model-list-item" :class="{selected:mcpSelectedId===server.id}" @click="editMcp(server)"><span class="model-state" :class="{configured:server.status==='connected'}"></span><span><strong>{{server.name}}</strong><small>{{server.transport}} · {{server.status}}</small></span><ChevronDown :size="14"/></button></div><div class="model-form-grid"><label>服务名称<input v-model="mcpDraft.name" placeholder="我的 MCP 服务"/></label><label>传输<select v-model="mcpDraft.transport"><option value="streamable_http">Streamable HTTP</option><option value="sse">Legacy SSE（仅保存配置）</option></select></label><label class="full-span">Endpoint<input v-model="mcpDraft.endpoint" placeholder="https://example.com/mcp"/></label><label>鉴权<select v-model="mcpDraft.auth_type"><option value="none">无</option><option value="bearer">Bearer</option><option value="api_key">X-API-Key</option></select></label><label>密钥<input v-model="mcpDraft.auth_secret" type="password" placeholder="留空则保留已有密钥"/></label></div><div class="mcp-actions"><button class="secondary-btn" :disabled="!mcpSelectedId||mcpBusy" @click="connectMcp">连接测试</button><button class="text-btn" :disabled="!mcpSelectedId||mcpBusy" @click="refreshMcpTools">刷新工具</button></div><p role="status">{{mcpStatus}}</p><div class="tool-list"><article v-for="tool in mcpTools" :key="tool.id" class="tool-item"><strong>{{tool.name}}</strong><span>{{tool.description || '未提供描述'}}</span><small>{{tool.enabled?'已允许提出调用 · 执行前仍需确认':'默认停用'}}</small><button class="text-btn" @click="setMcpToolEnabled(tool)">{{tool.enabled?'停用':'启用工具'}}</button></article><p v-if="!mcpTools.length" class="memory-empty">连接并刷新后，这里会显示 MCP 工具。</p></div></div>          <div v-else-if="item.kind==='plugins'" class="window-form plugin-window"><div class="window-section-heading"><div><span class="section-eyebrow">CONTROLLED TOOL PACKS</span><h2>插件工具包</h2><p>仅导入 JSON 清单并绑定已发现的 MCP 工具；不会加载或运行插件代码。</p></div><div class="plugin-head-actions"><button class="secondary-btn" @click="downloadPluginExample">下载清单示例</button><button class="primary-btn" :disabled="pluginBusy" @click="pluginFileInput?.click()">{{pluginBusy?'安装中…':'导入 JSON 清单'}}</button><input ref="pluginFileInput" class="plugin-file-input" type="file" accept=".json,application/json" @change="importPluginFile"/></div></div><div class="plugin-safety-note"><ShieldCheck :size="15"/><span>插件与插件工具默认停用。先启用 MCP 源工具，再分别启用插件和插件工具；模型每次调用仍需在聊天中单独确认。</span></div><p class="plugin-feedback" role="status">{{pluginStatus}}</p><div class="plugin-list"><article v-for="plugin in plugins" :key="plugin.id" class="plugin-card"><div class="plugin-card-head"><div><strong>{{plugin.name}}</strong><span>v{{plugin.version}} · {{plugin.author||'未署名'}}</span></div><div class="plugin-card-actions"><button @click="togglePlugin(plugin)">{{plugin.enabled?'停用插件':'启用插件'}}</button><button class="plugin-remove" @click="removePlugin(plugin)">卸载</button></div></div><p>{{plugin.description}}</p><div v-if="plugin.permissions.length" class="plugin-permissions"><span v-for="permission in plugin.permissions" :key="permission">{{permission}}</span></div><div class="plugin-tools"><div v-for="tool in plugin.tools" :key="tool.id" class="plugin-tool-row"><div><strong>{{tool.alias}}</strong><small>{{tool.server_name}} / {{tool.tool_name}} · {{tool.base_tool_enabled?'源工具已启用':'请先启用 MCP 源工具'}} · 每次确认</small></div><button :disabled="!plugin.enabled" @click="togglePluginTool(plugin,tool)">{{tool.enabled?'停用工具':'授权工具'}}</button></div></div><small class="plugin-checksum">清单 SHA-256：{{plugin.checksum.slice(0,16)}}…</small></article><div v-if="!plugins.length" class="plugin-empty"><Puzzle :size="24"/><strong>还没有安装插件</strong><span>导入 JSON 工具包清单。清单只可绑定已发现的 MCP 工具，不能携带可执行代码。</span></div></div></div><div v-else-if="item.kind==='voice'" class="window-form voice-window"><div class="window-section-heading"><div><span class="section-eyebrow">VOICE</span><h2>设备语音</h2><p>v1 使用当前浏览器和系统提供的语音能力，不保存音频文件。</p></div></div><section class="voice-section"><h3>文字转语音</h3><p>使用浏览器可用的系统语音，不通过 YOSAKI 后端发送文字；所选系统语音是否使用云端服务由浏览器/操作系统决定。</p><label>语言<select v-model="voiceLocale" @change="saveVoiceSettings"><option value="zh-CN">中文（普通话）</option><option value="en-US">English (US)</option><option value="ja-JP">日本語</option></select></label><label>设备语音<select v-model="selectedVoiceURI" @change="saveVoiceSettings"><option value="">自动选择 {{voiceLocale}} 语音</option><option v-for="voice in speechVoices" :key="voice.voiceURI" :value="voice.voiceURI">{{voice.name}} · {{voice.lang}}</option></select></label><label>语速：{{voiceRate.toFixed(1)}}<input v-model.number="voiceRate" type="range" min="0.6" max="1.4" step="0.1" @change="saveVoiceSettings"/></label><div class="voice-actions"><button class="secondary-btn" @click="speakText('你好，我是阿夜。语音朗读测试完成。','voice-test')">测试朗读</button><button class="text-btn" @click="stopSpeaking"><VolumeX :size="14"/>停止</button></div></section><section class="voice-section"><h3>语音转文字</h3><p>优先使用浏览器支持的本机识别；识别文字会放入聊天输入框，由你检查后再发送。</p><button class="primary-btn" @click="requestSpeechInput">{{speechRecognitionRunning?'停止语音识别':'开始语音输入'}}</button><p class="voice-status" role="status">{{speechStatus}}</p><p class="voice-privacy">如果本机识别不可用，YOSAKI 会先询问你是否允许使用浏览器语音识别服务；该服务可能将本次音频发送到浏览器供应商处理。默认不会启动此模式。</p></section></div><div v-else-if="item.kind==='settings'" class="window-form"><div class="window-section-heading"><div><span class="section-eyebrow">WORKSPACE SETTINGS</span><h2>工作台设置</h2><p>窗口布局会自动保存在当前浏览器。</p></div><button class="text-btn" @click="restoreLayout"><RefreshCw :size="14"/>恢复布局</button></div><div class="setting-tile"><LayoutGrid :size="17"/><div><strong>浮动窗口布局</strong><span>支持拖动、缩放、最小化和多窗口叠加。</span></div></div><div class="setting-tile"><ShieldCheck :size="17"/><div><strong>隐私优先</strong><span>当前页面不会把密钥写入浏览器存储。</span></div></div><div class="backup-panel"><h3>数据备份</h3><p>导出完整工作区快照并使用备份密码加密。账户信息也包含在加密文件内；模型 API Key、MCP 密钥和登录会话会主动剔除，恢复后需要重新登录并配置密钥。</p><label class="backup-passphrase">备份密码<input v-model="backupPassphrase" type="password" autocomplete="new-password" minlength="12" placeholder="至少 12 个字符；单独安全保管"/></label><div class="backup-actions"><button class="secondary-btn" :disabled="backupBusy" @click="exportBackup">导出加密备份</button><button class="text-btn" :disabled="backupBusy" @click="backupFileInput?.click">导入加密备份</button><input ref="backupFileInput" class="plugin-file-input" type="file" accept=".ybackup,application/vnd.yosaki.backup,application/octet-stream" @change="importBackup"/></div><p class="backup-status" role="status">{{backupStatus}}</p></div></div>
          <div v-else class="placeholder-panel"><div class="placeholder-icon" :style="{color:feature(item.kind).accent}"><component :is="feature(item.kind).icon" :size="25"/></div><h2>{{feature(item.kind).title}}</h2><p>{{feature(item.kind).description}}</p><span class="placeholder-status">{{feature(item.kind).status}}</span><div class="placeholder-line"><Grip :size="15"/> 这个功能会沿用同一套可移动窗口。</div></div>
        </div>
      </article>
    </section>
  </section>
  <div v-if="speechConsentPrompt" class="speech-consent-backdrop" role="presentation"><section class="speech-consent" role="dialog" aria-modal="true" aria-labelledby="speech-consent-title"><h2 id="speech-consent-title">本机语音识别不可用</h2><p>继续后将启动浏览器语音识别服务；当前音频可能发送至浏览器供应商处理。YOSAKI 不会保存音频，也不会自动发送识别出的文字。</p><div><button class="secondary-btn" @click="speechConsentPrompt=false">取消</button><button class="primary-btn" @click="confirmRemoteSpeech">继续并开始识别</button></div></section></div></div>
</template>
